import unittest

from archive import archive_attachment, archive_document


class ArchiveTests(unittest.TestCase):
    def test_allowed_operations_keep_result_state_and_events(self):
        cases = [
            (archive_document, ("owner",)),
            (archive_attachment, ("owner", "reader")),
            (archive_attachment, ("other", "maintainer")),
        ]
        for operation, args in cases:
            with self.subTest(operation=operation.__name__, args=args):
                resource = {"owner_id": "owner", "id": "resource", "archived": False}
                previous_event = {"kind": "created"}
                events = [previous_event]
                self.assertEqual(operation(*args, resource, events), "resource")
                self.assertEqual(resource, {"owner_id": "owner", "id": "resource", "archived": True})
                self.assertEqual(events, [previous_event, {"kind": "archived", "id": "resource", "actor": args[0]}])

    def test_denied_operations_leave_state_and_events_unchanged(self):
        cases = [
            (archive_document, ("other",), "Only the owner may archive documents"),
            (archive_attachment, ("other", "reader"), "Only the owner or a maintainer may archive attachments"),
            (archive_attachment, ("other", "admin"), "Only the owner or a maintainer may archive attachments"),
        ]
        for operation, args, message in cases:
            with self.subTest(operation=operation.__name__, args=args):
                resource = {"owner_id": "owner", "id": "resource", "archived": False}
                events = []
                with self.assertRaisesRegex(PermissionError, message):
                    operation(*args, resource, events)
                self.assertFalse(resource["archived"])
                self.assertEqual(events, [])

    def test_repeated_archive_still_emits_each_event(self):
        for operation, args in [(archive_document, ("owner",)), (archive_attachment, ("owner", "reader"))]:
            with self.subTest(operation=operation.__name__):
                resource = {"owner_id": "owner", "id": "resource", "archived": True}
                events = []
                for _ in range(2):
                    self.assertEqual(operation(*args, resource, events), "resource")
                self.assertEqual(events, [{"kind": "archived", "id": "resource", "actor": "owner"}] * 2)


if __name__ == "__main__":
    unittest.main()

