PROMPTS = {
    "implementation": """Use the local write-code skill at .agents/skills/write-code/SKILL.md. Complete these three independent fixture tasks in their own folders:
1. script/: create sum_csv.py, a small Python standard-library CLI accepting a CSV path. Sum its amount column exactly, print just the total, support negative values, and print 0 for a header-only file. Reject missing columns, invalid numbers and non-finite numbers with a nonzero exit and useful stderr.
2. checkout/: implement app.checkout(items), returning the existing payment provider's receipt. Validate the items using the existing domain module before payment, calculate the total in cents and charge once through the existing payment adapter. Payment failures must remain visible. Preserve the existing module responsibilities and client configuration.
3. authorization/: reduce duplicated archive bookkeeping in archive.py while preserving the two functions' signatures and existing permission policies, results and events.
Exercise the implemented behavior with disposable inputs. Keep changes within these task folders, use no third-party dependencies, and report the files and actual checks. Do not write outside this fixture or contact external services.
""",
    "review": """Use the local write-code skill at .agents/skills/write-code/SKILL.md in read-only review mode. Review reservation.py and payments.py for correctness, maintainability and the adequacy of their tests. Callers provide SQLite connections in autocommit mode (isolation_level=None); the service runs multiple concurrent workers against one database. The payment client is an external service; the included SDK is a synthetic fixture. Report actionable findings with file, line, impact and useful verification. You may run existing tests and use disposable scratch data to investigate, but leave all supplied source and test files unchanged. Do not contact external services or write outside this fixture.
""",
}


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def supplied_hashes(root):
    return {str(path.relative_to(root)): digest(path) for path in root.rglob("*.py")}


def prepare(revision):
    destination = TASK_ROOT / revision
    if destination.exists():
        raise SystemExit(f"Refusing to overwrite existing trial: {destination}")
    for case, files in (("implementation", FILES), ("review", REVIEW_FILES)):
        root = destination / case
        root.mkdir(parents=True)
        skill = root / ".agents/skills/write-code/SKILL.md"
        skill.parent.mkdir(parents=True)
        shutil.copyfile(SOURCE, skill)
        (root / "AGENTS.md").write_text(
            "# Independent synthetic fixture\n\nUse only this fixture's instructions and local write-code skill. "
            "No owner context, installation changes, external writes or publishing are part of this task. "
            "The parent owns comparison and acceptance. No native goal was requested.\n"
        )
        for name, text in files.items():
            path = root / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
        subprocess.run(["git", "init", "-q", str(root)], check=True)
        (root / "prompt.txt").write_text(PROMPTS[case])
        (root / "initial-hashes.json").write_text(json.dumps(supplied_hashes(root), indent=2) + "\n")
    (destination / "source.json").write_text(json.dumps({"skill_sha256": digest(SOURCE), "source": str(SOURCE)}, indent=2) + "\n")
    print(f"Prepared {revision}: {destination}", flush=True)


def run_case(revision, case):
    root = TASK_ROOT / revision / case
    command = ["codex", "exec", "--ephemeral", "--json", "--sandbox", "workspace-write",
               "-c", 'approval_policy="never"', "-c", 'model_reasoning_effort="high"',
               "--cd", str(root), "--output-last-message", str(root / "response.txt"), "-"]
    started = time.monotonic()
    with (root / "events.jsonl").open("w") as output, (root / "stderr.txt").open("w") as errors:
        process = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=output, stderr=errors, text=True)
        process.stdin.write((root / "prompt.txt").read_text())
        process.stdin.close()
        try:
            code = process.wait(timeout=300)
            timed_out = False
        except subprocess.TimeoutExpired:
            process.terminate()
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()
            code, timed_out = process.returncode, True
    result = {"case": case, "exit_code": code, "timed_out": timed_out,
              "elapsed_seconds": round(time.monotonic() - started, 2),
              "skill_sha256": digest(root / ".agents/skills/write-code/SKILL.md")}
    (root / "run.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps(result), flush=True)
    return result


def run(revision):
    with ThreadPoolExecutor(max_workers=2) as executor:
        results = list(executor.map(lambda case: run_case(revision, case), PROMPTS))
    if any(result["exit_code"] != 0 or result["timed_out"] for result in results):
        raise SystemExit(1)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("action", choices=("prepare", "run"))
    parser.add_argument("revision")
    arguments = parser.parse_args()
    {"prepare": prepare, "run": run}[arguments.action](arguments.revision)


if __name__ == "__main__":
    main()
